window.kbPageData["views/entry/k-4e76244fcace718e"] = {"key":"entry/k-4e76244fcace718e","state":{"route":"entry/k-4e76244fcace718e"},"node":{"id":"k-4e76244fcace718e","mode":"k","title":"两期比重与增长率","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["部分占整体的比重上升时，部分增长率大于整体增长率","部分占比上升当且仅当部分增速高于整体增速"],"qs":["江苏 2024 C类 行测#120","江苏 2025 C类 行测#120"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":0,"directorySummary":"在统计口径一致、部分和整体的基期量及整体的现期量均为正时，部分占整体的比重上升，说明部分增长率高于整体增长率。比重下降则说明部分增长率低于整体增长率。","review":{"definition":"在统计口径一致、部分和整体的基期量及整体的现期量均为正时，部分占整体的比重上升，说明部分增长率高于整体增长率。比重下降则说明部分增长率低于整体增长率。","explanation":"现期比重除以基期比重，等于部分的增长倍数（1＋部分增长率）除以整体的增长倍数（1＋整体增长率）。第120题中，M市旅游及相关产业增加值占地区生产总值的比重由2022年的3.7%升至2023年的4.0%，因此该产业增加值增速高于全市地区生产总值增速，C项可以推出。题目要求选出不能推出的一项，B项所需的A级景区游客中的过夜人次未在材料中给出。","references":[],"evidence":"当比重上升时，部分增长率>整体增长率","disposition":"独立词条","basis":"据原题和解析编释。","title":"两期比重与增长率","related":[],"examFocus":{"江苏 2024 C类 行测#120":"先区分单季出口占比与累计出口占比，再用单季占比的变化判断出口额与进出口总额的环比增速关系。","江苏 2025 C类 行测#120":"比较旅游及相关产业增加值与地区生产总值的增速时可看两期比重，核验游客占比时则需确认分子和分母属于同一统计范围。"}},"readings":[{"origin":"k-4e76244fcace718e","title":"两期比重与增长率","qs":["江苏 2025 C类 行测#120"],"definition":"在统计口径一致、部分和整体的基期量及整体的现期量均为正时，部分占整体的比重上升，说明部分增长率高于整体增长率。比重下降则说明部分增长率低于整体增长率。","explanation":"现期比重除以基期比重，等于部分的增长倍数（1＋部分增长率）除以整体的增长倍数（1＋整体增长率）。第120题中，M市旅游及相关产业增加值占地区生产总值的比重由2022年的3.7%升至2023年的4.0%，因此该产业增加值增速高于全市地区生产总值增速，C项可以推出。题目要求选出不能推出的一项，B项所需的A级景区游客中的过夜人次未在材料中给出。","evidence":"当比重上升时，部分增长率>整体增长率","doubt":"","references":[]},{"origin":"k-d5b1bb8023a919ec","title":"两期比重与增长率","qs":["江苏 2024 C类 行测#120"],"definition":"基期部分量和两期整体量均为正时，部分量与整体量的增长率按同一基期计算。部分量增速高于、等于或低于整体量增速时，部分所占比重分别上升、持平或下降，反过来也成立。","explanation":"现期比重与基期比重之比，等于（1＋部分量增速）除以（1＋整体量增速）。本题以2023年第一季度为环比基期，第二季度出口额占进出口总额的比重上升，说明出口额的环比增速高于进出口总额的环比增速，因此B项成立。","evidence":"当比重上升时，a>b","doubt":"","references":[]}]},"questions":{"江苏 2024 C类 行测#120":{"paper":"江苏 2024 C类 行测","n":120,"mod":"资料分析","src":["3f1ec77ae8a18519b57e.pdf",25],"asrc":["02d6b49839583bdaf297.pdf",36],"card":"4584a3a1bfa83e9094021720","links":[{"id":"k-4e76244fcace718e","role":"解题依据","why":"在基期部分量和两期整体量均为正时，占比上升可推出出口额环比增速高于进出口总额环比增速。"}]},"江苏 2025 C类 行测#120":{"paper":"江苏 2025 C类 行测","n":120,"mod":"资料分析","src":["ffc394a1c160f331ec57.pdf",25],"asrc":["d1de3b437151c05b769e.pdf",36],"card":"03c471d7e233eb659516e3da","links":[{"id":"k-4e76244fcace718e","role":"解题依据","why":"材料给出的产业增加值占比变化可用来判断产业与全市经济的增速关系。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-4e76244fcace718e":[["江苏 2024 C类 行测#120"],["江苏 2025 C类 行测#120"]]}};
